<?php
namespace App\Http\Controllers;
use App\Services\{SecurityAudit,ProviderPasswords,HistoryPage};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class PlatformSupportController
{
 private const KEYS=['admin','provider_id','provider_member_id','provider_member_version','pending_guest_invitation','provider_auth_method','provider_password_version','guest_id','guest_password_account','guest_password_version'];
 private function guard(Request $r):void{abort_unless($r->session()->get('platform_admin')===true,403);abort_unless(\Illuminate\Support\Facades\Schema::hasTable('security_audit_events'),503,'Előbb futtasd az adatbázis-frissítést: php artisan migrate --force');}
 public function support(Request $r){$this->guard($r);if($r->isMethod('GET'))return response()->json(['active'=>($support=$r->session()->get('platform_support'))?array_intersect_key($support,array_flip(['providerId','providerName','startedAt'])):null]);
  if($r->isMethod('DELETE')||$r->is('api/platform/support/stop')){$saved=$r->session()->get('platform_support');abort_unless($saved,422,'Nincs aktív segítségnyújtási belépés.');$this->end($r,$saved);return response()->json(['url'=>'/foadmin/szolgaltatok']);}
  $v=$r->validate(['providerId'=>'required|integer|min:1','confirmed'=>'required|accepted']);$provider=DB::table('salon_state')->select('id','data->settings->name as name')->find($v['providerId']);abort_unless($provider,404);if($provider->id!==1)abort_unless(DB::table('providers')->where('id',$provider->id)->where('active',true)->exists(),422,'A szolgáltató fiókja nem aktív.');abort_if($r->session()->has('platform_support'),409,'Előbb térj vissza a főadminhoz.');
  SecurityAudit::platform($r,'support_start',(int)$provider->id);$saved=$r->session()->only(self::KEYS);$r->session()->forget(self::KEYS);$r->session()->regenerate();$r->session()->put(['platform_support'=>['providerId'=>(int)$provider->id,'providerName'=>$provider->name,'startedAt'=>now()->toISOString(),'returnAuth'=>$saved],'admin'=>true,'provider_id'=>(int)$provider->id,'provider_auth_method'=>'support','provider_password_version'=>ProviderPasswords::version((int)$provider->id)]);return response()->json(['url'=>'/munkaterulet/naptar?provider='.$provider->id]);
 }
 private function end(Request $r,array $saved):void{SecurityAudit::platform($r,'support_end',(int)$saved['providerId']);$r->session()->forget(array_merge(self::KEYS,['platform_support']));$r->session()->regenerate();$r->session()->put($saved['returnAuth']??[]);}
 public function audit(Request $r){$this->guard($r);$v=$r->validate(['q'=>'nullable|string|max:150','event'=>'nullable|in:all,login,support_start,support_end,support_write,guest_edit,guest_delete,guest_blacklist','actor'=>'nullable|in:all,platform,provider,member,guest','providerId'=>'nullable|integer|min:1']);$q=DB::table('security_audit_events')->orderByDesc('id');if(!empty($v['event'])&&$v['event']!=='all')$q->where('event',$v['event']);if(!empty($v['actor'])&&$v['actor']!=='all')$q->where('actor_type',$v['actor']);if(!empty($v['providerId']))$q->where('provider_id',$v['providerId']);if(!empty($v['q']))$q->where(function($q)use($v){$key='%'.str_replace(['!','%','_'],['!!','!%','!_'],$v['q']).'%';$q->whereRaw("ip LIKE ? ESCAPE '!'",[$key])->orWhereRaw("CAST(actor_id AS CHAR) LIKE ? ESCAPE '!'",[$key])->orWhereRaw("CAST(provider_id AS CHAR) LIKE ? ESCAPE '!'",[$key]);});$page=HistoryPage::query($q,$r,30);$providerIds=collect($page['items'])->pluck('provider_id')->filter()->unique();$names=DB::table('salon_state')->whereIn('id',$providerIds)->select('id','data->settings->name as name')->get()->pluck('name','id');$guestNames=DB::table('guest_accounts')->whereIn('id',collect($page['items'])->where('actor_type','guest')->pluck('actor_id'))->pluck('name','id');$members=DB::table('provider_members')->whereIn('id',collect($page['items'])->where('actor_type','member')->pluck('actor_id'))->pluck('email','id');foreach($page['items'] as $row){$row->created_at=\Carbon\CarbonImmutable::parse($row->created_at,config('app.timezone'))->toIso8601String();$row->provider_name=$names[$row->provider_id]??null;$row->actor_name=match($row->actor_type){'platform'=>'Főadmin','provider'=>$row->provider_name,'member'=>$members[$row->actor_id]??null,'guest'=>$guestNames[$row->actor_id]??null,default=>null};}return response()->json($page)->header('Cache-Control','no-store');}
}
